use vstd::prelude::*;

verus! {
    // Specification for the interleave function
    fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
        requires
            s1.len() == s2.len() && s2.len() == s3.len(), // All arrays must have the same length
            0 <= s1.len() as i32 && (3 * (s1.len() as i32)) <= i32::MAX, // Length constraints
        ensures
            res.len() == 3 * s1.len(), // Resulting array must have length 3n
            forall|i: nat| 0 <= i < s1.len() ==> res[3 * i] == s1[i] && res[3 * i + 1] == s2[i] && res[3 * i + 2] == s3[i], // Interleaving condition
    {
        let n = s1.len() as nat; // Length of the input arrays
        let mut res: Vec<i32> = Vec::new(); // Initialize the result vector

        // Loop to interleave the elements
        let mut i: nat = 0; // Index for the input arrays
        while i < n
            invariant
                0 <= i <= n, // Index must be within bounds
                res.len() == 3 * i, // Result length must be 3 times the current index
                res.len() <= 3 * n, // Result length must not exceed 3n
            decreases n - i, // Decreases clause for termination
        {
            // Push elements from the input arrays into the result
            res.push(s1[i as usize]);
            res.push(s2[i as usize]);
            res.push(s3[i as usize]);
            i = i + 1; // Increment the index
        }
        res // Return the interleaved result
    }
}

